<script setup lang="ts">
import {ElButton, ElSelect, ElOption, ElInput, ElTable, ElTableColumn, ElPagination, vLoading} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {api,type Account} from '../../api'
import {confirmAction} from '../../shared/confirm'
import {base,reasonText,type Restaurant,type PageResult} from './types'
import './dining.css'
const props=defineProps<{account:Account}>()
const canManage=computed(()=>props.account.permissionCodes.includes('dining.manage'))
const items=ref<Restaurant[]>([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),error=ref('')
const selected=ref<Restaurant[]>([]),busy=ref(false),notice=ref('')
const enabled=ref(''),storeId=ref(''),warehouses=ref<{id:string;name:string}[]>([]),warehouseError=ref('')
let generation=0,warehouseGeneration=0
async function loadWarehouses(){const current=++warehouseGeneration;warehouseError.value='';warehouses.value=[];const choices:{id:string;name:string}[]=[];try{let nextPage=1;let count=0;do{const result=await api<PageResult<{id:string;name:string}>>(`${base}/order-stores?pageSize=100&page=${nextPage++}`);if(current!==warehouseGeneration)return;choices.push(...result.items);count=result.total;if(!result.items.length)break}while(choices.length<count);if(current===warehouseGeneration)warehouses.value=choices}catch(e){if(current===warehouseGeneration)warehouseError.value=reasonText(e)}}
async function status(enabled:boolean,rows=selected.value){if(busy.value||!canManage.value||!rows.length)return;const owner=props.account.accountId,current=generation;const targets=rows.map(r=>({restaurantId:r.id,expectedRevision:r.revision}));if(!await confirmAction(`确定${enabled?'启用':'停用'} ${rows.length} 家餐饮店：${rows.map(r=>r.name).join('、')}？停用后不可继续提交新订单，已创建订单继续履约。`))return;if(owner!==props.account.accountId||current!==generation||!canManage.value)return;busy.value=true;error.value='';try{await api(`${base}/restaurants/batch-status`,{method:'POST',body:JSON.stringify({items:targets,enabled})});if(owner!==props.account.accountId)return;notice.value='餐饮店状态已更新。';await load()}catch(e){if(owner===props.account.accountId)error.value=reasonText(e)}finally{if(owner===props.account.accountId)busy.value=false}}
async function load(){const current=++generation;loading.value=true;error.value='';items.value=[];selected.value=[];try{const result=await api<PageResult<Restaurant>>(`${base}/restaurants?${new URLSearchParams({page:String(page.value),pageSize:'20',search:search.value.trim(),...(enabled.value?{enabled:enabled.value}:{}),...(storeId.value?{storeId:storeId.value}:{})})}`);if(current===generation){items.value=result.items;total.value=result.total}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
function query(){if(busy.value)return;page.value=1;load()}
watch(()=>[props.account.accountId,props.account.permissionCodes.join(',')],()=>{busy.value=false;selected.value=[];notice.value='';enabled.value='';storeId.value='';search.value='';page.value=1;load();loadWarehouses()},{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>餐饮联盟店</h1><p>仅限扫码访问，使用系统匹配前置仓的库存与履约；缺货不切仓。</p></div><RouterLink v-if="canManage" to="/dining-alliance/restaurants/new"><el-button type="primary">新增餐饮店</el-button></RouterLink></header><section class="panel"><form class="toolbar" @submit.prevent="query"><el-input v-model="search" aria-label="搜索餐饮店" :disabled="busy" placeholder="搜索店名" clearable style="width:280px"/><el-select v-model="enabled" aria-label="餐饮店状态" placeholder="全部状态" clearable :disabled="busy" style="width:160px"><el-option label="全部状态" value=""/><el-option label="启用" value="true"/><el-option label="停用" value="false"/></el-select><el-select v-model="storeId" aria-label="筛选履约前置仓" placeholder="全部前置仓" clearable :disabled="busy" style="width:220px"><el-option label="全部前置仓" value=""/><el-option v-for="warehouse in warehouses" :key="warehouse.id" :label="warehouse.name" :value="warehouse.id"/></el-select><el-button native-type="submit" :disabled="busy" :loading="loading">查询</el-button></form><p v-if="warehouseError" role="alert" class="error">前置仓筛选读取失败：{{warehouseError}} <el-button @click="loadWarehouses">重试前置仓</el-button></p><p v-if="error" class="error" role="alert">{{error}} <el-button @click="load">重试</el-button></p><div v-if="canManage" class="toolbar"><span>已选 {{selected.length}} 家（仅当前页）</span><el-button :disabled="!selected.length||busy||loading" @click="status(true)">批量启用</el-button><el-button :disabled="!selected.length||busy||loading" @click="status(false)">批量停用</el-button><RouterLink v-if="selected.length===1" :to="`/dining-alliance/restaurants/${selected[0]!.id}`"><el-button :disabled="busy">编辑</el-button></RouterLink></div><p v-if="notice" role="status">{{notice}}</p><div class="table-wrap"><el-table v-loading="loading" :data="items" empty-text="暂无餐饮店" @selection-change="selected=$event"><el-table-column v-if="canManage" type="selection" width="50" :selectable="()=>!busy&&!loading"/><el-table-column label="餐饮店" min-width="180"><template #default="{row}"><RouterLink :to="`/dining-alliance/restaurants/${row.id}`">{{row.name}}</RouterLink></template></el-table-column><el-table-column prop="address" label="地址" min-width="220"/><el-table-column label="履约前置仓" min-width="150"><template #default="{row}">{{row.fulfillmentStore?.name||'尚未匹配'}}</template></el-table-column><el-table-column prop="tableCount" label="桌数" width="80"/><el-table-column label="状态" width="90"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column v-if="canManage" label="操作" min-width="210"><template #default="{row}"><RouterLink :to="`/dining-alliance/restaurants/${row.id}`"><el-button link :disabled="busy">编辑</el-button></RouterLink><RouterLink :to="`/dining-alliance/restaurants/${row.id}?tab=tables`"><el-button link :disabled="busy">桌码管理</el-button></RouterLink><el-button link :disabled="busy||loading" @click="status(!row.enabled,[row as Restaurant])">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table></div><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="if(!busy){page=$event;load()}"/></section></section></template>
